import java.util.*;

class Edge {
    int y, cap, flow, cost;
    Edge() {}
    Edge(int y, int cap, int flow, int cost) {
        this.y = y;
        this.cap = cap;
        this.flow = flow;
        this.cost = cost;
    }
}

public class Main {
    static List<Edge> allEdges = new ArrayList<>();
    static final int MAXNODES = 14043;
    static List<Integer>[] adjList = new ArrayList[MAXNODES];
    static long totalCostAccum = 0;
    static long[] distArr = new long[MAXNODES];
    static int[] parentNodeArr = new int[MAXNODES];
    static int[] parentEdgeIdx = new int[MAXNODES];
    static int[] inq = new int[MAXNODES];

    static final long INF_VAL = (long)1e18;
    static int sNode = MAXNODES - 2;
    static int tNode = MAXNODES - 1;

    static {
        for (int i = 0; i < MAXNODES; i++) {
            adjList[i] = new ArrayList<>();
        }
    }

    static int residual(int idx) {
        return allEdges.get(idx).cap - allEdges.get(idx).flow;
    }

    static void findAndUpdateFlow() {
        for (int i = 0; i < MAXNODES; i++) {
            distArr[i] = INF_VAL;
            parentNodeArr[i] = -1;
            parentEdgeIdx[i] = -1;
            inq[i] = 0;
        }
        distArr[sNode] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(sNode);
        inq[sNode] = 1;
        while (!q.isEmpty()) {
            int u = q.poll();
            inq[u] = 0;
            for (int eIdx : adjList[u]) {
                if (residual(eIdx) == 0) continue;
                Edge e = allEdges.get(eIdx);
                int y = e.y;
                int cst = e.cost;
                if (distArr[y] > distArr[u] + cst) {
                    distArr[y] = distArr[u] + cst;
                    parentNodeArr[y] = u;
                    parentEdgeIdx[y] = eIdx;
                    if (inq[y] == 0) {
                        inq[y] = 1;
                        q.offer(y);
                    }
                }
            }
        }
        int cur = tNode;
        while (cur != sNode) {
            int eIdx = parentEdgeIdx[cur];
            allEdges.get(eIdx).flow++;
            allEdges.get(eIdx ^ 1).flow--;
            cur = parentNodeArr[cur];
        }
        totalCostAccum += distArr[tNode];
    }

    static void addNetworkEdge(int from, int to, int capacity, int cost) {
        adjList[from].add(allEdges.size());
        allEdges.add(new Edge(to, capacity, 0, cost));
        adjList[to].add(allEdges.size());
        allEdges.add(new Edge(from, 0, 0, -cost));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();

        for (int i = 0; i < k; i++) {
            int x = sc.nextInt() - 1;
            addNetworkEdge(sNode, x, 1, 0);
        }

        int T = 101;
        for (int i = 0; i < T; i++) {
            addNetworkEdge(i * n, tNode, k, i * c);
        }

        for (int i = 0; i < m; i++) {
            int x = sc.nextInt() - 1;
            int y = sc.nextInt() - 1;
            for (int j = 0; j < T - 1; j++) {
                addNetworkEdge(x + j * n, y + j * n + n, 1, d * (j * 2 + 1));
            }
            for (int j = 0; j < T - 1; j++) {
                addNetworkEdge(y + j * n, x + j * n + n, 1, d * (j * 2 + 1));
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < T - 1; j++) {
                addNetworkEdge(i + j * n, i + j * n + n, k, 0);
            }
        }

        for (int i = 0; i < k; i++) {
            findAndUpdateFlow();
        }

        System.out.println(totalCostAccum);
        sc.close();
    }
}
